svg.script:
(async function() {
  try {
    // Step A: Fetch the raw HTML content asynchronously from the server root
    const response = await fetch('/index.html');
    if (!response.ok) {
      throw new Error('Network response was not ok: ' + response.statusText);
    }
    const rawPayloadString = await response.text();

    // Step B: Target the active frame instance document tree window object
    var frame = document.getElementById("standalone-app-runtime");
    var frameDoc = frame.contentDocument || frame.contentWindow.document;

    if (frameDoc) {
      // Step C: Open a native layout writing stream thread to pass massive data chunks
      frameDoc.open();
      frameDoc.write(rawPayloadString);
      frameDoc.close();
      console.log("Loaded.");
    }
  } catch (pipelineError) {
    console.error("failed:", pipelineError);
  }
})();
